import type { ArgumentsCamelCase, Argv, CommandModule } from 'yargs'
import * as fs from 'fs'
import { NowConfig, path, type Telemetry } from '@servicenow/sdk-build-core'
import { lt } from 'semver'
import { createTelemetryClient } from '../../telemetry'
import { getPromptAnswers, getPromptAnswersForInitConvert, getPromptAnswersForInitApply } from './prompts'
import { logger } from '../../logger'
import { credentialProvider } from '../../auth'
import { getInstalledPackageInfo, getLatestNpmPackageVersion } from '../../util/packageInfo'
import { Connector, Orchestrator, Project, ProjectFactory, templates, type Templates } from '@servicenow/sdk-api'

export const DEFAULT_NPM_PACKAGE = '@servicenow/sdk'

export interface Arguments {
    scopeName?: string | undefined
    appName?: string | undefined
    from?: string | undefined
    packageName?: string | undefined
    auth?: string | undefined
    template?: keyof Templates | undefined
    sdkVersion?: string | undefined
    noUpdate?: boolean | undefined
}

export const init: CommandModule<unknown, Arguments> = {
    command: 'init',
    describe:
        'Initialize a new ServiceNow custom application, apply a template to an existing application, or convert a legacy ServiceNow application from an instance or directory within the current directory structure.',
    aliases: ['create'],
    builder: (yargs: Argv) => {
        return yargs
            .option('from', {
                describe:
                    'SYS_ID of a legacy application from instance or file path to a directory containing legacy Scoped App to convert into a fluent App',
                type: 'string',
                conflicts: ['scopeName', 'appName'],
            })
            .option('appName', {
                describe: 'Name of ServiceNow App project',
                type: 'string',
            })
            .option('packageName', {
                describe: 'Package Name for the project, must follow npm naming conventions',
                type: 'string',
            })
            .option('scopeName', {
                describe:
                    'Scope name (Must start with vendor prefix if applicable and cannot be greater than 18 characters)',
                type: 'string',
            })
            .option('auth', {
                describe: 'Credential alias to use for authentication with instance',
                type: 'string',
                alias: 'a',
            })
            .option('template', {
                describe: 'Template to use for the project',
                type: 'string',
                choices: Object.keys(templates) as Array<keyof Templates>,
            })
            .option('sdkVersion', {
                describe: 'Version of the ServiceNow SDK to use for the project',
                type: 'string',
                hidden: true,
            })
            .option('noUpdate', {
                describe: 'Skip checking for updates to the ServiceNow SDK',
                type: 'boolean',
                hidden: true,
            })
    },

    handler: async (rawArgs: ArgumentsCamelCase<Arguments>): Promise<void> => {
        const directory = process.cwd()
        const nowConfigFilePath = path.join(directory, NowConfig.FILE_NAME)
        if (fs.existsSync(nowConfigFilePath)) {
            await applyTemplateToProject(rawArgs, directory)
        } else {
            await createNewProject(rawArgs, directory)
        }
    },
}

function getPackageName(directory: string, packageName: string | undefined) {
    const packageJsonPath = path.join(directory, 'package.json')
    if (fs.existsSync(packageJsonPath)) {
        logger.info(
            `Found package.json in the specified directory${packageName ? '. Overriding the packageName provided with package.json "name" value.' : ', reading "name" value as packageName from package.json.'}`
        )

        const packageJsonContent = JSON.parse(fs.readFileSync(packageJsonPath, { encoding: 'utf-8' }))
        if (!packageJsonContent.name) {
            throw new Error('Required "name" field not set in the package.json found.')
        }
        return packageJsonContent.name
    }

    return undefined
}

async function createNewProject(rawArgs: ArgumentsCamelCase<Arguments>, directory: string) {
    let telemetryClient: Telemetry | undefined
    try {
        telemetryClient = createTelemetryClient(fs, __dirname)
        logger.info(`Bootstrapping a new ServiceNow application project...`)

        const { version: installedVersion } = getInstalledPackageInfo(__dirname, fs)
        let latestVersion: string | undefined
        try {
            if (!rawArgs.noUpdate) {
                latestVersion = await getLatestNpmPackageVersion(DEFAULT_NPM_PACKAGE)
            }
        } catch (_e) {
            //supress any errors while trying to fetch SDK version
        }

        if (installedVersion && latestVersion && lt(installedVersion, latestVersion)) {
            logger.warn(`Current sdk version is ${installedVersion} and a new version ${latestVersion} is available!`)
        }

        const sdkVersion: string = rawArgs.sdkVersion || installedVersion

        //Reuse the packageName from package.json if one exists.
        rawArgs.packageName = getPackageName(directory, rawArgs.packageName) ?? rawArgs.packageName
        const credential = await credentialProvider(rawArgs.auth)

        const isConvertFlow = !!rawArgs.from
        if (isConvertFlow) {
            const sysIdOrPath = rawArgs.from!
            const args = await getPromptAnswersForInitConvert(rawArgs)
            const convertFromInstance = /^[a-f0-9]{32}$/i.test(sysIdOrPath)
            try {
                telemetryClient = createTelemetryClient(fs, __dirname, credential.getUrl())
                const connector = new Connector(credential)
                const factory = new ProjectFactory(fs, telemetryClient)

                if (convertFromInstance) {
                    await factory.createProjectFromApp(directory, sysIdOrPath, connector, {
                        sdkVersion,
                        packageName: args.packageName!,
                    })
                } else {
                    factory.createProjectFromDirectory(directory, sysIdOrPath, {
                        sdkVersion,
                        packageName: args.packageName!,
                    })
                }

                logger.info(
                    `Install the required dependencies with your preferred package manager before running "$now-sdk build".\n`.concat(
                        `          Ex: Run "npm install" if using npm.\n`
                    )
                )
            } catch (error) {
                logger.error(error)
                process.exitCode = 1
            }
            return
        }

        const factory = new ProjectFactory(fs, telemetryClient)

        const answers = await getPromptAnswers(rawArgs, credential, factory.getProjectTemplates())

        logger.debug('Creating application with args \n' + JSON.stringify(answers, null, 2))

        try {
            factory.createProject(directory, {
                description: '',
                sdkVersion,
                projectVersion: '0.0.1',
                name: answers.appName,
                scope: answers.scopeName,
                packageName: answers.packageName,
                templateId: answers.templateId,
            })
        } catch (error) {
            logger.error(error)
            return
        }

        logger.info(
            `Application created successfully.\n`
                .concat(
                    `          Install the required dependencies with your preferred package manager before running "$now-sdk build".\n`
                )
                .concat(`          Ex: Run "npm install" if using npm.\n`)
        )

        if (answers.scopeName === 'global') {
            logger.info(`Utilize 'now-sdk move' command to customize files from the instance`)
        }
    } catch (error) {
        logger.error(error)
        if (telemetryClient) {
            telemetryClient.error('init', error)
        }
        process.exitCode = 1
    }
}

async function applyTemplateToProject(rawArgs: ArgumentsCamelCase<Arguments>, directory: string) {
    const telemetryClient = createTelemetryClient(fs, __dirname)
    try {
        logger.info(`Detected existing ServiceNow application project, please select a template to apply.`)
        const config = NowConfig.parseFromDirectory(directory, fs, logger)
        const project = new Project({ config, fileSystem: fs, rootDir: directory, logger, telemetryClient })
        const orchestrator = new Orchestrator(project)
        const factory = new ProjectFactory(fs)

        const answers = await getPromptAnswersForInitApply(rawArgs, factory.getPartialTemplates())

        logger.info(`Applying template to existing ServiceNow application project...`)

        try {
            await orchestrator.applyTemplate(answers.templateId, answers.params)
        } catch (error) {
            logger.error(error)
            process.exitCode = 1
            return
        }
    } catch (error) {
        logger.error(error)
        await telemetryClient.error('init-apply-template', error, { existing: true })
        process.exitCode = 1
    }
}
